import numpy as np
from PIL import Image,ImageDraw
ns={};exec(open('/app/output/skeletonize.py').read().split('# Overlay')[0],ns);sk=ns['a'];coords=np.argwhere(sk);H,W=sk.shape
idx=np.full(sk.shape,-1,int);idx[sk]=np.arange(len(coords));adj=[[] for _ in coords]
# reduce redundant 8-neighbour edges: keep diagonal only where neither adjacent orth pixel exists
for i,(y,x) in enumerate(coords):
 for dy,dx in [(0,1),(1,-1),(1,0),(1,1)]:
  yy,xx=y+dy,x+dx
  if yy>=H or xx<0 or xx>=W or not sk[yy,xx]:continue
  if dy and dx and (sk[y,xx] or sk[yy,x]):continue
  j=int(idx[yy,xx]);adj[i].append(j);adj[j].append(i)
# components
seen=set();comps=[]
for s in range(len(coords)):
 if s in seen:continue
 st=[s];seen.add(s);c=[]
 while st:
  u=st.pop();c.append(u)
  for v in adj[u]:
   if v not in seen:seen.add(v);st.append(v)
 comps.append(c)
print('components',len(comps))
# pair incident halfedges to minimize turn deviation from straight
pairs=[{} for _ in coords]
for u,nb in enumerate(adj):
 if len(nb)<2:continue
 dirs={v:(coords[v]-coords[u]).astype(float)/np.linalg.norm(coords[v]-coords[u]) for v in nb}
 unused=set(nb)
 while len(unused)>=2:
  # greedily choose straightest pair
  a,b=min(((a,b) for a in unused for b in unused if a<b),key=lambda ab:float(np.dot(dirs[ab[0]],dirs[ab[1]])))
  pairs[u][a]=b;pairs[u][b]=a;unused.remove(a);unused.remove(b)
# trace each unpaired half-edge, else cycles
used=set();paths=[]
def ekey(a,b):return (a,b) if a<b else (b,a)
# start all unpaired halfedges
starts=[]
for u,nb in enumerate(adj):
 for v in nb:
  if v not in pairs[u]: starts.append((u,v))
for start in starts:
 if ekey(*start) in used:continue
 path=[start[0]];u,v=start
 while True:
  e=ekey(u,v)
  if e in used:break
  used.add(e);path.append(v)
  w=pairs[v].get(u)
  if w is None:break
  u,v=v,w
 if len(path)>1:paths.append(path)
# remaining cycles
for u,nb in enumerate(adj):
 for v in nb:
  if ekey(u,v) in used:continue
  path=[u];a,b=u,v
  while ekey(a,b) not in used:
   used.add(ekey(a,b));path.append(b);w=pairs[b].get(a)
   if w is None:break
   a,b=b,w
  if len(path)>1:paths.append(path)
print('paths',len(paths),'coverededges',len(used),'edge total',sum(map(len,adj))//2)
for ci,c in enumerate(comps):
 ps=[p for p in paths if p[0] in set(c)]
 xs=coords[c,1];ys=coords[c,0]
 print(ci,len(ps),'bbox',(xs.min(),ys.min(),xs.max(),ys.max()),'pathlens',sorted([len(p) for p in ps],reverse=True)[:5])
# visualize distinct traces
im=np.array(Image.open('/app/target.png'));out=Image.fromarray(im.copy());d=ImageDraw.Draw(out)
for k,path in enumerate(paths):
 xy=[(int(coords[i,1]),int(coords[i,0])) for i in path];col=((k*67)%255,(k*139)%255,(k*191)%255)
 if len(xy)>1:d.line(xy,fill=col,width=2)
out.save('/app/output/seg_paths.png')
